INSERT INTO `news` (`id`, `title`, `description`, `image`, `author`, `views`, `is_published`, `created_at`, `updated_at`) VALUES
(1, 'В Северо-Западном округе к Крещенским купаниям готовят 12 купелей', '...', '6968f16d61018_2026-01-15.jpg', 'Администратор', 0, 1, '2026-01-15 10:53:49', '2026-05-25 11:54:53'),
(2, 'Зимняя ловля рыбы: правила безопасного поведения для рыбаков', '...', '6968f18747425_Untitled12-1.jpg', 'Администратор', 0, 1, '2026-01-15 10:54:15', '2026-05-25 11:54:53'),
(3, 'Прокуратура информирует', '...', '6968f1af9e3a0_изображение_2026-01-15_165448012.png', 'Администратор', 0, 1, '2026-01-15 10:54:55', '2026-05-25 11:54:53'),
(4, 'КТО ВОЗМЕЩАЕТ УЩЕРБ, ПРИЧИНЕННЫЙ ТРАНСПОРТНОМУ СРЕДСТВУ...', 'Взыскание ущерба за повреждённый автомобиль: кто должен платить?\r\nМногие водители, чьи автомобили пострадали в ДТП, оказываются в сложной ситуации: кому предъявлять требования о возмещении ущерба? Разбираемся, кто именно несёт материальную ответственность и на каких основаниях.\r\n\r\nОСАГО: первая линия защиты\r\nПри стандартной аварии ущерб возмещается страховой компанией виновника ДТП в рамках полиса ОСАГО. По общему правилу страховщик организует и оплачивает восстановительный ремонт повреждённого автомобиля потерпевшего на станции технического обслуживания. Закон защищает потерпевшего: страховщик не вправе без законных оснований заменить ремонт денежной выплатой с учётом износа деталей.\r\n\r\nМаксимальная сумма возмещения по ОСАГО за ущерб имуществу в 2025 году составляла 400 тысяч рублей. При оформлении аварии по европротоколу без вызова сотрудников ГИБДД лимит также составляет 400 тысяч рублей, но только при условии фотофиксации повреждений через специальное приложение и отсутствии разногласий между водителями. При наличии разногласий и фотофиксации лимит выплаты составляет 200 тысяч рублей. Если же водители просто заполнили бумажный бланк, не сделав фото, максимальная выплата снижается до 100 тысяч рублей. В 2025 году лимит при оформлении ДТП без участия ГАИ при наличии разногласий был увеличен со 100 до 200 тысяч рублей.\r\n\r\nКАСКО: дополнительная защита\r\nДобровольное страхование КАСКО покрывает ущерб автомобилю в самых разных ситуациях — от ДТП до затопления из-за паводка. Однако выплата по КАСКО производится за вычетом франшизы — суммы, указанной в договоре в процентах от страховой суммы или в фиксированном размере.\r\n\r\nВажно помнить: страховщик не компенсирует ущерб, если случай не признан страховым. Не подлежат возмещению убытки, причинённые в ходе военных действий, взрыва, забастовки или уничтожения автомобиля по решению суда.\r\n\r\nА если страховки недостаточно или нет вообще?\r\nЕсли суммы страхового возмещения по ОСАГО недостаточно для полного восстановления автомобиля, ущерб покрывается полисом КАСКО потерпевшего (если он оформлен). Когда же КАСКО нет, разница взыскивается непосредственно с владельца автомобиля, которым управлял виновник аварии.\r\n\r\nВ ситуации, когда у виновника ДТП отсутствует полис ОСАГО, ответственность полностью ложится на собственника транспортного средства (или на самого водителя, если он не является владельцем). В судебной практике встречаются случаи, когда гражданская ответственность виновника ДТП не была застрахована, и требование о возмещении ущерба предъявлялось ответчику на всю сумму стоимости восстановительного ремонта — и суд такие требования удовлетворял.\r\n\r\nКто отвечает: собственник или водитель?\r\nЭто один из самых частых вопросов. По закону обязанность возмещения вреда возлагается на юридическое лицо или гражданина, которые владеют источником повышенной опасности на праве собственности, аренды, по доверенности или ином законном основании. Если водитель управлял автомобилем на законном основании (например, по доверенности, в силу трудовых отношений или по договору аренды), ущерб может быть взыскан как с него, так и с собственника — суд в каждом случае решает индивидуально.\r\n\r\nОсобого внимания заслуживают случаи, когда водитель работает по найму. Если сотрудник попал в ДТП на служебном автомобиле, для привлечения его к полной материальной ответственности необходимо, чтобы ДТП было признано административным правонарушением. При этом суды часто отказывают работодателям во взыскании с работника полной стоимости ремонта, даже если с ним заключён договор о полной материальной ответственности.\r\n\r\nКогда требуют заплатить сверх страховки?\r\nВажно знать: если страховая компания выплатила возмещение, но этих денег не хватило на полноценный ремонт, потерпевший вправе взыскать оставшуюся разницу непосредственно с виновника ДТП. Эта возможность закреплена гражданским законодательством: вред, причинённый имуществу гражданина, подлежит возмещению в полном объёме лицом, причинившим вред.\r\n\r\nУголовная ответственность не освобождает от гражданского иска\r\nОсобо тяжкие ДТП с причинением тяжкого вреда здоровью или со смертью потерпевших квалифицируются по статье 264 УК РФ. Уголовное наказание не заменяет гражданско-правовую ответственность: потерпевшая сторона вправе заявить гражданский иск о возмещении материального ущерба в рамках уголовного дела.\r\n\r\nСудебная практика: верховный суд разъяснил важный нюанс\r\nВ июне 2026 года Верховный Суд РФ обратил внимание судов на необходимость проверять добросовестность действий участников страховых правоотношений. В одном из дел автовладелец доставил повреждённый в ДТП автомобиль на станцию техобслуживания, но ремонт не начинал, а затем потребовал денежной выплаты как при полной гибели машины. ВС РФ указал, что противоречивое поведение стороны в договорных отношениях (эстоппель) недопустимо, и судам следует убеждаться, что одна из сторон не злоупотребляет своим правом. Это важный сигнал для страховщиков и водителей: при разрешении споров ключевое значение приобретает не только буква закона, но и добросовестность участников.\r\n\r\nЧто делать, если автомобиль пострадал?\r\nПервым делом — зафиксируйте все обстоятельства происшествия: вызовите сотрудников ГИБДД или оформите европротокол с фотофиксацией через приложение. Затем обратитесь в страховую компанию виновника с заявлением о выплате по ОСАГО. Если сумма страховки недостаточна — предъявите требования непосредственно виновнику ДТП или собственнику автомобиля. Во всех сложных ситуациях рекомендуется обращаться к квалифицированному юристу, специализирующемуся на автостраховании и ДТП, который поможет правильно определить ответчика и подготовить необходимые документы.', '6a202ee3a773d_insurance-agent-working-car-accident-claim-process.jpg', 'Администратор', 0, 1, '2026-01-15 10:55:46', '2026-06-03 13:40:51'),
(5, 'Как правильно оказать помощь при ударе током?', 'Удар током — одна из самых опасных травм: невидимая, но способная за секунды остановить сердце. От правильных и быстрых действий спасателя зависит жизнь пострадавшего. Главное правило: сначала обесточьте источник, затем — спасайте человека.\r\n\r\nШаг 1. Обеспечьте свою безопасность\r\nНи в коем случае не хватайте пострадавшего голыми руками, пока он под напряжением — вы сами станете частью цепи.\r\n\r\nВыключите рубильник, автомат или выдерните вилку из розетки. Если это невозможно — перерубите провод топором с сухой деревянной рукояткой (в быту) или специальным инструментом.\r\n\r\nОтбросьте провод сухой палкой, доской, пластиковым предметом. Не используйте металлические и мокрые предметы.\r\n\r\nОттащите пострадавшего только за сухую одежду (не за тело!), если он всё ещё касается источника. Действуйте одной рукой или наденьте резиновые перчатки, сухую обувь, встаньте на изолирующий коврик (сухую доску, резину).\r\n\r\nШаг 2. Оцените состояние пострадавшего\r\nПосле отключения тока сразу проверьте:\r\n\r\nесть ли сознание;\r\n\r\nдышит ли он;\r\n\r\nпрощупывается ли пульс на сонной артерии.\r\n\r\nШаг 3. Вызовите скорую помощь\r\nЗвоните 103 или 112 даже при лёгких симптомах (слабость, нарушение ритма сердца). Сообщите диспетчеру:\r\n\r\nчто произошёл удар током;\r\n\r\nесть ли пострадавший без сознания;\r\n\r\nналичие ожогов.\r\n\r\nШаг 4. Начните оказание помощи\r\nВ зависимости от состояния:\r\n\r\nЕсли человек в сознании:\r\n\r\nУложите его в безопасное место.\r\n\r\nПриподнимите ноги (положите валик).\r\n\r\nПриложите холод (через ткань!) к местам входа и выхода тока — обычно это две точки на теле.\r\n\r\nНаблюдайте до приезда врачей: удар током может вызвать скрытые нарушения ритма сердца.\r\n\r\nЕсли без сознания, но дышит и есть пульс:\r\n\r\nПоверните голову набок (восстановительное положение).\r\n\r\nРасстегните стесняющую одежду.\r\n\r\nСледите за дыханием.\r\n\r\nЕсли нет дыхания и пульса:\r\n👉 Немедленно начинайте сердечно-лёгочную реанимацию:\r\n\r\n30 надавливаний на центр груди (глубина 5–6 см, ритм 100–120 в минуту).\r\n\r\n2 вдоха «рот в рот» (если есть защитная плёнка).\r\n\r\nПродолжайте до приезда скорой или появления признаков жизни.\r\n\r\nЧего делать категорически нельзя ❌\r\n❌ Трогать пострадавшего под напряжением без изоляции.\r\n\r\n❌ Искать пульс на запястье (при поражении током он может не прощупываться, проверяйте сонную артерию).\r\n\r\n❌ Закрывать небольшие ожоги пластырем или мазать маслом.\r\n\r\n❌ Останавливать реанимацию, если устали — попросите кого-то сменить вас.\r\n\r\n❌ Оставлять пострадавшего одного, даже если он очнулся и говорит, что всё в порядке (возможно позднее фибрилляция желудочков).\r\n\r\nОсобые случаи\r\nВысокое напряжение (ЛЭП, трансформатор) — не приближайтесь ближе 8–10 метров! Звоните в МЧС и ждите специалистов. В зоне «шагового напряжения» передвигайтесь гусиным шагом, не отрывая ступней от земли.\r\n\r\nУдар молнией — отключения тока не требуется, начинайте реанимацию сразу. Пострадавшие от молнии не «сохраняют заряд».\r\n\r\nКороткая памятка (для шпаргалки)\r\nОтключи питание или отбрось провод палкой.\r\n\r\nВызови 103/112.\r\n\r\nНет пульса и дыхания → непрямой массаж сердца + вдохи.\r\n\r\nЕсть пульс, но без сознания → уложи на бок.\r\n\r\nЖди врачей.\r\n\r\nПомните: при ударе током счёт идёт на минуты. Ваши решительные действия могут вернуть человека к жизни. Безопасность спасателя — первое условие спасения.\r\n\r\nизображение с сайта magnific.com', '6a202e88bd5be_2206.i301.007.F.m004.c9.Safety precaution at workplace isometric background.jpg', 'Администратор', 0, 1, '2026-01-15 10:56:27', '2026-06-03 13:39:20');

